/* Midnight Bloom Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="midnight-bloom-light"] {
  --background: hsl(300 0% 97.37%);
  --foreground: hsl(0 0% 19.89%);
  --card: hsl(300 50% 100%);
  --card-foreground: hsl(0 0% 19.89%);
  --popover: hsl(300 50% 100%);
  --popover-foreground: hsl(0 0% 19.89%);
  --primary: hsl(246.69 73.88% 63.53%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(210.39 72.75% 78.81%);
  --secondary-foreground: hsl(0 0% 19.89%);
  --muted: hsl(45.01 14.71% 75%);
  --muted-foreground: hsl(320 0% 43.34%);
  --accent: hsl(72.18 16.43% 49.99%);
  --accent-foreground: hsl(300 50% 100%);
  --destructive: hsl(359.91 86.11% 60.55%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(340 0% 83.14%);
  --input: hsl(340 0% 83.14%);
  --ring: hsl(246.69 73.88% 63.53%);
  --chart-1: hsl(246.69 73.88% 63.53%);
  --chart-2: hsl(282.25 43% 47.74%);
  --chart-3: hsl(274.62 99.95% 25.6%);
  --chart-4: hsl(218.54 76.87% 65.45%);
  --chart-5: hsl(207.26 44.15% 49.24%);
  --radius: 0.5rem;
  --sidebar: hsl(300 0% 97.37%);
  --sidebar-foreground: hsl(0 0% 19.89%);
  --sidebar-primary: hsl(246.69 73.88% 63.53%);
  --sidebar-primary-foreground: hsl(300 50% 100%);
  --sidebar-accent: hsl(72.18 16.43% 49.99%);
  --sidebar-accent-foreground: hsl(300 50% 100%);
  --sidebar-border: hsl(340 0% 83.14%);
  --sidebar-ring: hsl(246.69 73.88% 63.53%);
  --font-sans: Montserrat, sans-serif;
  --font-serif: Playfair Display, serif;
  --font-mono: Source Code Pro, monospace;
  --shadow-color: hsl(0 0% 0%);
  --shadow-opacity: 0.1;
  --shadow-blur: 10px;
  --shadow-spread: -2px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 5px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 5px 10px -2px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 5px 10px -2px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 2px 4px -3px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 4px 6px -3px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 8px 10px -3px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 5px 10px -2px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

